# Add college field to all entries
for entry in additional_entries:
    entry['college'] = 'Ivy College of Business'

# Combine and deduplicate
all_entries = existing + additional_entries
seen_ids = set()
unique_entries = []
for entry in all_entries:
    if entry['id'] not in seen_ids:
        seen_ids.add(entry['id'])
        unique_entries.append(entry)

print(f"Added: {len(additional_entries)} new entries")
print(f"Total unique: {len(unique_entries)}")

# Save complete list
with open('../data/ivy_faculty.json', 'w', encoding='utf-8') as f:
    json.dump(unique_entries, f, indent=2)

print(f"Saved to ivy_faculty.json")
